        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeRarProgress.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface RarProgress: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeRarProgress.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface RarProgress: handle missing in uniffiClone")
            }
